-- Workshop bays and the car on each (WEB-022). Tables generated by prisma migrate diff, then
-- reviewed; checks, the one-car-per-bay index and the triggers are hand-written.

-- AlterTable
ALTER TABLE "workshop"."job_card" ADD COLUMN     "bay_id" UUID;

-- CreateTable
CREATE TABLE "workshop"."bay" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "company_id" UUID NOT NULL,
    "branch_id" UUID NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "bay_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "bay_branch_id_code_key" ON "workshop"."bay"("branch_id", "code");

-- AddForeignKey
ALTER TABLE "workshop"."job_card" ADD CONSTRAINT "job_card_bay_id_fkey" FOREIGN KEY ("bay_id") REFERENCES "workshop"."bay"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "workshop"."bay" ADD CONSTRAINT "bay_company_id_branch_id_fkey" FOREIGN KEY ("company_id", "branch_id") REFERENCES "org"."branch"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written rules -------------------------------------------------------

ALTER TABLE workshop.bay
  ADD CONSTRAINT bay_code_valid CHECK (code ~ '^[A-Z0-9][A-Z0-9-]{0,9}$'),
  ADD CONSTRAINT bay_name_present CHECK (length(btrim(name)) > 0);

-- One car per bay; delivered and cancelled jobs hold no bay.
CREATE UNIQUE INDEX job_card_one_per_bay ON workshop.job_card (bay_id) WHERE bay_id IS NOT NULL;
ALTER TABLE workshop.job_card
  ADD CONSTRAINT job_closed_has_no_bay CHECK (status NOT IN ('delivered', 'cancelled') OR bay_id IS NULL);

-- A job is placed only on an active bay of its own branch.
CREATE OR REPLACE FUNCTION workshop.guard_job_bay() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.bay_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.bay_id IS DISTINCT FROM OLD.bay_id) THEN
    IF NOT EXISTS (SELECT 1 FROM workshop.bay b
                    WHERE b.id = NEW.bay_id AND b.branch_id = NEW.branch_id
                      AND b.company_id = NEW.company_id AND b.active) THEN
      RAISE EXCEPTION 'job_bay_invalid' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER job_card_bay BEFORE INSERT OR UPDATE OF bay_id ON workshop.job_card
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_job_bay();

-- A bay with a car on it cannot be deactivated; bays are never deleted (history).
CREATE OR REPLACE FUNCTION workshop.guard_bay() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'bay_delete_forbidden' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.branch_id <> OLD.branch_id OR NEW.company_id <> OLD.company_id OR NEW.code <> OLD.code THEN
    RAISE EXCEPTION 'bay_identity_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.active AND NOT NEW.active AND EXISTS (SELECT 1 FROM workshop.job_card j WHERE j.bay_id = NEW.id) THEN
    RAISE EXCEPTION 'bay_occupied' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER bay_guard BEFORE UPDATE OR DELETE ON workshop.bay
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_bay();

-- Timeline: moves between bays.
ALTER TABLE workshop.job_event DROP CONSTRAINT job_event_kind_valid;
ALTER TABLE workshop.job_event ADD CONSTRAINT job_event_kind_valid CHECK (kind IN (
  'created', 'status', 'assignment', 'task_done', 'task_reopened', 'qc_pass', 'qc_fail', 'note', 'updated',
  'inspection', 'photo_added', 'photo_removed',
  'addition_proposed', 'addition_approved', 'addition_declined', 'addition_withdrawn', 'bay'));
